/*
  # Update Terms & Conditions and Privacy Policy — Version 2.0.0

  ## Overview
  Replaces the existing terms content with a comprehensive, Zimbabwe-law-aligned
  Terms & Conditions and Privacy Policy document. This version:
  - Clearly establishes UniLink as a technology intermediary platform only
  - Limits developer/platform liability to the fullest extent permitted by law
  - References applicable Zimbabwean statutes (Consumer Protection Act,
    Cyber and Data Protection Act, Postal and Telecommunications Act,
    Electronic Transactions and Electronic Commerce Act, Competition Act)
  - Creates enforceable indemnity clauses for both shoppers and delivery partners
  - Inserts a standalone privacy policy field into the terms_and_conditions table

  ## Changes
  1. Modified Tables
     - `terms_and_conditions`: adds `privacy_policy` column (text) if not present
  2. Data
     - Updates the active terms record (version 2.0.0) with full legal text
     - Inserts privacy policy text into the new column
*/

-- Add privacy_policy column if it does not exist
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'terms_and_conditions' AND column_name = 'privacy_policy'
  ) THEN
    ALTER TABLE terms_and_conditions ADD COLUMN privacy_policy text;
  END IF;
END $$;

-- Deactivate any existing active terms
UPDATE terms_and_conditions SET is_active = false WHERE is_active = true;

-- Insert comprehensive Version 2.0.0
INSERT INTO terms_and_conditions (version, content, privacy_policy, effective_date, is_active)
VALUES (
  '2.0.0',

-- ============================================================
